Method.Source:
    /// <summary>
    /// Caption visible
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METBYODCompService));
        this.parmMethodName(methodStr(METBYODCompService, processOperation));
        this.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        this.parmDialogCaption("@MET:METBYODCompEntity");
    }

/// <summary>
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:METBYODCompEntity";
}

    /// <summary>
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METBYODCompController controller;

        controller = new METBYODCompController();
        controller.parmArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METBYODCompController construct()
{
    return new METBYODCompController();
